from decimal import Decimal, InvalidOperation, localcontext
from typing import Union

__all__ = ["convert", "MASS_UNITS", "UnitError"]

# Grams per unit, as exact Decimal factors.
MASS_UNITS = {
    "kg": Decimal("1000"),
    "g": Decimal("1"),
    "mg": Decimal("0.001"),
}

# Enough precision for any in-range ratio of the three units (max factor 1e6).
_PRECISION = 60


class UnitError(ValueError):
    """Raised for negative values or unsupported units."""


Number = Union[str, int, float, Decimal]


def _to_decimal(value: Number) -> Decimal:
    """Convert *value* to Decimal without introducing binary float noise."""
    if isinstance(value, Decimal):
        dec = value
    elif isinstance(value, bool):
        # bool is an int subclass; treat as unsupported to avoid 1/0 surprises.
        raise UnitError("boolean values are not supported")
    elif isinstance(value, int):
        dec = Decimal(value)
    elif isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            raise UnitError("value must be a finite number")
        # str() gives the shortest repr that round-trips, avoiding 0.1 -> 0.1000000000000000055511151231257827
        dec = Decimal(str(value))
    elif isinstance(value, str):
        try:
            dec = Decimal(value.strip())
        except InvalidOperation:
            raise UnitError(f"value is not a valid decimal number: {value!r}")
    else:
        raise UnitError(f"unsupported value type: {type(value).__name__}")

    if not dec.is_finite():
        raise UnitError("value must be a finite number")
    if dec < 0:
        raise UnitError(f"negative values are not supported: {value!r}")
    return dec


def _check_unit(unit: str, name: str) -> str:
    if not isinstance(unit, str):
        raise UnitError(f"{name} must be a string unit, got {type(unit).__name__}")
    if unit not in MASS_UNITS:
        raise UnitError(
            f"unsupported unit for {name}: {unit!r}; supported units: "
            f"{sorted(MASS_UNITS)}"
        )
    return unit


def _format(dec: Decimal) -> str:
    """Plain decimal string, insignificant trailing zeros removed."""
    if dec == 0:
        return "0"
    sign, digits, exponent = dec.as_tuple()
    text = format(dec, "f")  # plain notation, never scientific
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text or "0"


def convert(value: Number, from_unit: str, to_unit: str) -> str:
