{"content": """"Unit tests for convert.convert (exact Decimal mass conversion)."""

import json
import unittest
from decimal import Decimal

from convert import MASS_UNITS, UnitError, convert


class TestExactConversions(unittest.TestCase):
    def test_kg_to_g(self):
        self.assertEqual(convert("1.25", "kg", "g"), "1250")
        self.assertEqual(convert(1, "kg", "g"), "1000")
        self.assertEqual(convert(Decimal("0.001"), "kg", "g"), "1")

    def test_g_to_mg(self):
        self.assertEqual(convert("0.1", "g", "mg"), "100")
        self.assertEqual(convert(1, "g", "mg"), "1000")

    def test_mg_to_g(self):
        self.assertEqual(convert("1234", "mg", "g"), "1.234")
        self.assertEqual(convert(Decimal("1"), "mg", "g"), "0.001")

    def test_zero(self):
        self.assertEqual(convert(0, "g", "mg"), "0")
        self.assertEqual(convert("0", "kg", "g"), "0")
        self.assertEqual(convert("0.000", "mg", "kg"), "0")

    def test_identity_and_round_trip(self):
        self.assertEqual(convert("1.234", "g", "g"), "1.234")
        value = "1.234"
        self.assertEqual(convert(convert(value, "g", "mg"), "mg", "g"), value)

    def test_trailing_zeros_stripped(self):
        self.assertEqual(convert("1.2500", "kg", "g"), "1250")
        self.assertEqual(convert("10.00", "g", "mg"), "10000")
        self.assertEqual(convert("2.500", "mg", "g"), "0.0025")
        self.assertNotIn(".", convert("1.0", "kg", "g"))

    def test_float_input_has_no_binary_noise(self):
        self.assertEqual(convert(0.1, "g", "mg"), "100")
        self.assertEqual(convert(1.25, "kg", "g"), "1250")

    def test_no_scientific_notation(self):
        self.assertEqual(convert(Decimal("1E-7"), "g", "mg"), "0.0001")
        self.assertNotIn("E", convert(Decimal("1E-7"), "g", "mg").upper())

    def test_extreme_but_exact(self):
        self.assertEqual(convert("0.000001", "kg", "mg"), "1000")
        self.assertEqual(convert("1000000", "mg", "kg"), "1")

    def test_units_dict_matches_documented_set(self):
        self.assertEqual(set(MASS_UNITS), {"kg", "g", "mg"})


class TestRejections(unittest.TestCase):
    def test_negative_values(self):
        for value in (-1, "-1", "-0.5", Decimal("-3"), -0.0001):
            with self.subTest(value=value):
                with self.assertRaises(UnitError):
                    convert(value, "kg", "g")

    def test_unsupported_units(self):
        for bad in ("lb", "KG", "grams", "", " g", "t"):
            with self.subTest(unit=bad):
                with self.assertRaises(UnitError):
                    convert("1", bad, "g")
                with self.assertRaises(UnitError):
                    convert("1", "g", bad)

    def test_invalid_numbers(self):
        for bad in ("abc", "", "1.2.3", "nan", "inf", None, [], True):
            with self.subTest(value=bad):
                with self.assertRaises(UnitError):
                    convert(bad, "g", "mg")

    def test_non_string_unit_type(self):
        with self.assertRaises(UnitError):
            convert("1", None, "g")


class TestResultJsonValues(unittest.TestCase):
    """The four values that must appear in result.json, produced by real calls."""

    CASES = [
        ("1.25", "kg", "g", "1250"),
        ("0.1", "g", "mg", "100"),
        ("1234", "mg", "g", "1.234"),
        ("0", "g", "mg", "0"),
    ]

    def test_produces_expected_list(self):
        produced = [convert(v, f, t) for v, f, t, _ in self.CASES]
        self.assertEqual(produced, ["1250", "100", "1.234", "0"])

    def test_matches_result_json_on_disk(self):
        produced = [convert(v, f, t) for v, f, t, _ in self.CASES]
        with open("result.json", encoding="utf-8") as fh:
            data = json.load(fh)
        self.assertEqual(data["results"], produced)
        self.assertEqual(data["results"], ["1250", "100", "1.234", "0"])
        for item in data["results"]:
            self.assertIsInstance(item, str)


