def _format(dec: Decimal) -> str:
    """Plain decimal string, insignificant trailing zeros removed.

    Always returns a non-negative plain decimal (never scientific notation,
    never "-0"), because convert() rejects negative inputs.
    """
    if dec.is_zero():
        return "0"
    text = format(dec, "f")  # plain notation, never scientific
    if "." in text:
        text = text.rstrip("0").rstrip(".")

